<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import { HostEvent, HostSurface } from '../../platform/host-adapter.mjs'; import { createInteractionsApi, InteractionsApiError } from './domain/interactions-api.mjs'; import { interactionsListViewModel } from './domain/interactions-view.mjs'; import InteractionsListDesktop from './desktop/InteractionsListDesktop.vue'; import InteractionsListMobile from './mobile/InteractionsListMobile.vue'; import InteractionCreateDesktop from './desktop/InteractionCreateDesktop.vue'; import InteractionCreateMobile from './mobile/InteractionCreateMobile.vue';
const props = defineProps({ surface: { type: String, required: true }, adapter: { type: Object, default: null }, hostUnavailable: { type: Boolean, default: false } }); const emit = defineEmits(['back']); const api = createInteractionsApi(); const state = reactive({ phase: 'loading', rows: [], total: 0, page: 1, pageSize: 20, search: '', permissions: null, mode: 'read', partner: null, partnerResults: [], searchingPartners: false, saving: false, saveError: '', error: null }); const safeArea = ref(props.adapter?.getSafeArea?.() || {}); const unsubscribers = []; const isNative = computed(() => props.surface === HostSurface.NATIVE); const canCreate = computed(() => state.permissions?.modules?.interactions?.includes('create') === true); const safeAreaStyle = computed(() => Object.fromEntries(['top', 'right', 'bottom', 'left'].flatMap((side) => Number.isFinite(Number(safeArea.value?.[side])) ? [[`--mds-mobile-safe-${side}`, `${Number(safeArea.value[side])}px`]] : [])));
function setError(error) { state.error = error instanceof InteractionsApiError ? error : new InteractionsApiError({ status: 0, code: 'INTERACTIONS_NETWORK', message: 'Không thể tải tương tác. Vui lòng thử lại.' }); state.phase = 'error'; }
async function load({ page = state.page, search = state.search } = {}) { if (props.hostUnavailable) { setError(new InteractionsApiError({ status: 503, code: 'HOST_ADAPTER_UNAVAILABLE', message: 'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.' })); return; } state.phase = 'loading'; state.error = null; try { const [payload, session] = await Promise.all([api.getList({ page, pageSize: state.pageSize, search }), api.getCurrentUser()]); const model = interactionsListViewModel(payload); state.rows = model.rows; state.total = model.total; state.page = model.page; state.pageSize = model.pageSize; state.search = search; state.permissions = session?.permissions || null; state.mode = 'read'; state.phase = 'ready'; } catch (error) { setError(error); } }
function search(value) { load({ page: 1, search: value }); } function changePage(page) { load({ page, search: state.search }); } function beginCreate() { if (!canCreate.value) return; state.mode = 'create'; state.partner = null; state.partnerResults = []; state.saveError = ''; } async function searchPartners(query) { if (!query) { state.partnerResults = []; return; } state.searchingPartners = true; try { state.partnerResults = await api.searchEntities(query); } catch (error) { state.saveError = error.message; } finally { state.searchingPartners = false; } } function selectPartner(partner) { state.partner = partner; state.partnerResults = []; } async function save(payload) { state.saving = true; state.saveError = ''; try { await api.create(payload); await load(); } catch (error) { state.saveError = error.message; } finally { state.saving = false; } } async function goBack() { if (isNative.value && props.adapter) { await props.adapter.goBack({ reason: 'interactions-list' }); return; } emit('back'); } function listen() { if (!props.adapter || props.hostUnavailable) return; unsubscribers.push(props.adapter.subscribe(HostEvent.VIEWPORT, (payload) => { if (payload?.safeArea) safeArea.value = { ...safeArea.value, ...payload.safeArea }; })); unsubscribers.push(props.adapter.subscribe(HostEvent.LIFECYCLE, (payload) => { if (payload?.state === 'foreground' && state.mode === 'read') load(); })); } onMounted(() => { listen(); load(); }); onBeforeUnmount(() => { while (unsubscribers.length) unsubscribers.pop()(); });
</script>
<template><div v-if="state.phase === 'loading'" :class="isNative ? 'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]' : 'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'" :style="isNative ? safeAreaStyle : undefined"><MSpinner :size="28" class="text-[var(--mds-brand-600)]" /></div><section v-else-if="state.phase === 'error'" :class="isNative ? 'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]' : 'min-h-[360px] bg-[var(--mds-bg-page)]'" :style="isNative ? safeAreaStyle : undefined"><MMobileTopBar v-if="isNative" title="Lịch sử tương tác" @back="goBack" /><MEmptyState :title="state.error.status === 403 ? 'Bạn không có quyền xem tương tác' : 'Không thể mở tương tác'" :description="state.error.message" /></section><InteractionCreateMobile v-else-if="isNative && state.mode === 'create'" :partner="state.partner" :results="state.partnerResults" :searching="state.searchingPartners" :saving="state.saving" :server-error="state.saveError" :safe-area-style="safeAreaStyle" @cancel="state.mode = 'read'" @search="searchPartners" @select="selectPartner" @save="save" /><InteractionsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :loading="false" :can-create="canCreate" :safe-area-style="safeAreaStyle" @back="goBack" @create="beginCreate" @search="search" @page="changePage" /><InteractionCreateDesktop v-else-if="state.mode === 'create'" :partner="state.partner" :results="state.partnerResults" :searching="state.searchingPartners" :saving="state.saving" :server-error="state.saveError" @cancel="state.mode = 'read'" @search="searchPartners" @select="selectPartner" @save="save" /><InteractionsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :loading="false" :can-create="canCreate" @create="beginCreate" @search="search" @page="changePage" /></template>
